const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.query) {
  errors.push('Missing required parameter: query');
}

if (!body.google_api_key) {
  errors.push('Missing required parameter: google_api_key');
}

if (!body.anthropic_api_key && !body.openai_api_key) {
  errors.push('Missing API key: anthropic_api_key or openai_api_key required for recipe extraction');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

const prefs = body.preferences || {};

// Generate job_id if callback_url provided but no job_id
const crypto = require('crypto');
const job_id = body.job_id || (body.callback_url ? crypto.randomUUID() : null);

return [{
  json: {
    valid: true,
    query: body.query,
    google_api_key: body.google_api_key,
    anthropic_api_key: body.anthropic_api_key,
    openai_api_key: body.openai_api_key,
    user_id: body.user_id,
    language: prefs.language || 'fr',
    max_videos: prefs.max_videos || 1,
    prefer_short: prefs.prefer_short || false,
    n8n_webhook_url: process.env.N8N_WEBHOOK_URL || 'http://localhost:5678',
    callback_url: body.callback_url || null,
    job_id: job_id
  }
}];

const input = $input.first().json;

// Store all context needed for async processing
return [{
  json: {
    ...input,
    async_mode: true,
    job_started_at: new Date().toISOString()
  }
}];

const validationData = $('Validate Input').first().json;
const crypto = require('crypto');

const body = {
  success: false,
  job_id: validationData.job_id,
  status: 'failed',
  error: {
    code: 404,
    message: 'No YouTube videos found for query',
    status: 'NOT_FOUND'
  },
  meta: {
    provider: 'youtube',
    query: validationData.query
  }
};

const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callback_url: validationData.callback_url,
    body: body,
    signature: signature
  }
}];

