const input = $input.first().json;
const prevData = $('Extract Video Info').first().json;
const transcriptData = $('Transcribe Video').first().json;
const validationData = $('Validate Input').first().json;

try {
  if (input.error) {
    return [{
      json: {
        success: false,
        job_id: validationData.job_id,
        status: validationData.callback_url ? 'failed' : undefined,
        error: {
          code: 500,
          message: input.error.message || 'LLM extraction failed',
          status: 'EXTRACTION_ERROR'
        },
        meta: { provider: 'youtube+anthropic' },
        callback_url: validationData.callback_url
      }
    }];
  }

  const content = input.content?.[0]?.text || '{}';
  let recipe;

  try {
    recipe = JSON.parse(content);
  } catch (e) {
    // Try to extract JSON from response
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    recipe = jsonMatch ? JSON.parse(jsonMatch[0]) : { title: 'Parse error', raw: content };
  }

  return [{
    json: {
      success: true,
      job_id: validationData.job_id,
      status: validationData.callback_url ? 'completed' : undefined,
      data: {
        source: 'youtube',
        video: prevData.video,
        recipe,
        transcript_excerpt: (transcriptData.data?.transcript || '').substring(0, 500) + '...'
      },
      meta: {
        provider: 'youtube+anthropic',
        models_used: ['gemini-2.5-flash', 'claude-haiku-4-5-20251001'],
        tokens_used: {
          transcription: 0,
          extraction: (input.usage?.input_tokens || 0) + (input.usage?.output_tokens || 0)
        }
      },
      callback_url: validationData.callback_url
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      job_id: validationData.job_id,
      status: validationData.callback_url ? 'failed' : undefined,
      error: {
        code: 500,
        message: 'Failed to process recipe: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'youtube' },
      callback_url: validationData.callback_url
    }
  }];
}

const input = $input.first().json;
const crypto = require('crypto');

// Build callback body (exclude callback_url from response)
const body = {
  success: input.success,
  job_id: input.job_id,
  status: input.status
};

if (input.success) {
  body.data = input.data;
} else {
  body.error = input.error;
}

body.meta = input.meta;

// Generate HMAC signature (RFC-040 format)
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(body);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callback_url: input.callback_url,
    body: body,
    signature: signature
  }
}];

